import { pool } from "./db.js";

export const HEIC_PATCHES = [
  { jpgFilename: "photo_1789923419577_ob1hmf.jpg", heicFilename: "photo_1789923419577_ob1hmf.heic", base64Data: "" },
  { jpgFilename: "photo_1789928441157_xibwtf.jpg", heicFilename: "photo_1789928441157_xibwtf.heic", base64Data: "" },
  { jpgFilename: "photo_1789929126099_p4rjm4.jpg", heicFilename: "photo_1789929126099_p4rjm4.heic", base64Data: "" },
];

export async function applyHeicBackfill() {
  if (!pool) return;
  for (const patch of HEIC_PATCHES) {
    try {
      const buffer = Buffer.from(patch.base64Data, "base64");
      // 1. Insert/update JPEG into uploaded_files
      await pool.query(
        `INSERT INTO uploaded_files (filename, mime_type, data)
         VALUES ($1, 'image/jpeg', $2)
         ON CONFLICT (filename) DO UPDATE SET data = EXCLUDED.data, mime_type = 'image/jpeg'`,
        [patch.jpgFilename, buffer],
      );

      // 2. Also update the heic row in uploaded_files so any legacy references to .heic serve the valid JPEG bytes!
      await pool.query(
        `UPDATE uploaded_files SET data = $1, mime_type = 'image/jpeg' WHERE filename = $2`,
        [buffer, patch.heicFilename],
      );

      // 3. Update candidate answers in application_submissions
      const oldUrl = `/uploads/${patch.heicFilename}`;
      const newUrl = `/uploads/${patch.jpgFilename}`;
      await pool.query(
        `UPDATE application_submissions
         SET answers = jsonb_set(
           answers,
           ARRAY[key],
           to_jsonb($2::text)
         )
         FROM (
           SELECT id, key
           FROM application_submissions, jsonb_each_text(answers)
           WHERE value = $1
         ) sub
         WHERE application_submissions.id = sub.id`,
        [oldUrl, newUrl],
      );
      console.log(`Backfilled ${patch.heicFilename} -> ${patch.jpgFilename}`);
    } catch (err) {
      console.error(`Error backfilling ${patch.heicFilename}:`, err);
    }
  }
}
